from fractions import Fraction
from math import isqrt
import json

# Given magnitudes (exact).
mag = {"a": Fraction(1), "b": Fraction(2), "c": Fraction(3)}
pairs = [("a", "b"), ("a", "c"), ("b", "c")]

def unsigned_angle(t1, t2):
    # Unsigned angle in degrees between two directions given in integer degrees.
    d = abs(t1 - t2) % 360
    return min(d, 360 - d)

# Enumerate planar configurations: a at 0 deg, b and c at integer-degree directions.
# Find every common pairwise angle alpha (0..180 deg) realizable by three planar directions.
valid_alphas = []
for alpha in range(0, 181):
    found = False
    for tb in range(-180, 181):
        if unsigned_angle(0, tb) != alpha:
            continue
        for tc in range(-180, 181):
            if unsigned_angle(0, tc) == alpha and unsigned_angle(tb, tc) == alpha:
                found = True
                break
        if found:
            break
    if found:
        valid_alphas.append(alpha)

# Exact cosine for each realizable angle that has an exact rational cosine here.
exact_cos = {0: Fraction(1), 120: Fraction(-1, 2)}

def sum_sq(cos_val):
    # |a+b+c|^2 = |a|^2+|b|^2+|c|^2 + 2*sum(|x||y|cos)
    s = sum(m * m for m in mag.values())
    for x, y in pairs:
        s += 2 * mag[x] * mag[y] * cos_val
    return s

def fmt_sqrt(q):
    # Exact square root of a non-negative rational, as a string.
    n, d = q.numerator, q.denominator
    rn, rd = isqrt(n), isqrt(d)
    if rn * rn == n and rd * rd == d:
        r = Fraction(rn, rd)
        return str(r.numerator) if r.denominator == 1 else f"{r.numerator}/{r.denominator}"
    return f"sqrt({q})"

results = []
evidence_cases = []
for alpha in valid_alphas:
    if alpha not in exact_cos:
        continue
    sq = sum_sq(exact_cos[alpha])
    results.append(fmt_sqrt(sq))
    evidence_cases.append({
        "pairwise_angle_deg": alpha,
        "cos": f"{exact_cos[alpha].numerator}/{exact_cos[alpha].denominator}",
        "magnitude_squared": f"{sq.numerator}/{sq.denominator}",
        "magnitude": fmt_sqrt(sq),
    })

if not results:
    print("UNSUPPORTED")
else:
    out = {
        "final_answer": " or ".join(results),
        "evidence": {
            "realizable_equal_pairwise_angles_deg": valid_alphas,
            "cases": evidence_cases,
        },
    }
    print(json.dumps(out))
